function solve(s, t) {
  const n = s.length;
  const m = t.length;
  const dp = [];
  for (let i = 0; i <= n; i++) {
    dp.push(new Array(m + 1).fill(false));
  }
  for (let j = 0; j <= m; j++) dp[n][j] = true;
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      if (s[i] === t[j]) dp[i][j] = dp[i + 1][j + 1];
      else dp[i][j] = dp[i][j + 1];
    }
  }
  return dp[0][0];
}

function solve(s, t) {
  let i = 0;
  for (let j = 0; j < t.length && i < s.length; j++) {
    if (t[j] === s[i]) i++;
  }
  return i === s.length;
}
